```python
import os
import json
import traceback
from flask import Flask, request, jsonify, Response
from flask_cors import CORS
from cerebras.cloud.sdk import Cerebras

app = Flask(__name__)
CORS(app)

cerebras_api_key = os.environ.get("CEREBRAS_API_KEY")
if not cerebras_api_key:
    raise ValueError("CEREBRAS_API_KEY környezeti változó nincs beállítva!")

client = Cerebras(api_key=cerebras_api_key)

conversations = {}

@app.route('/health', methods=['GET'])
def health_check():
    return jsonify({"status": "healthy", "model": "gpt-oss-120b"}), 200

@app.route('/api/chat', methods=['POST'])
def chat():
    try:
        data = request.get_json(silent=True)
        if not data:
            return jsonify({"error": "Hiányzó request body"}), 400
        user_message = data.get('message', '').strip()
        conversation_id = data.get('conversation_id', 'default')
        if not user_message:
            return jsonify({"error": "Üres üzenet"}), 400
        if conversation_id not in conversations:
            conversations[conversation_id] = []
        conversations[conversation_id].append({
            "role": "user",
            "content": user_message
        })
        print(f"[{conversation_id}] User: {user_message[:100]}...")
        response = client.chat.completions.create(
            model="gpt-oss-120b",
            messages=conversations[conversation_id],
            max_completion_tokens=65000,
            reasoning_effort="low",
            temperature=0.7,
            stream=False
        )
        ai_response = response.choices[0].message.content
        conversations[conversation_id].append({
            "role": "assistant",
            "content": ai_response
        })
        print(f"[{conversation_id}] AI válasz generálva: {len(ai_response)} karakter")
        return jsonify({
            "response": ai_response,
            "conversation_id": conversation_id,
            "model": "gpt-oss-120b",
            "tokens_used": response.usage.total_tokens if hasattr(response, 'usage') else None
        }), 200
    except Exception as e:
        print(f"❌ Hiba történt: {str(e)}")
        traceback.print_exc()
        return jsonify({"error": f"Szerver hiba: {str(e)}"}), 500

@app.route('/api/chat/stream', methods=['POST'])
def chat_stream():
    try:
        data = request.get_json(silent=True)
        if not data:
            return jsonify({"error": "Hiányzó request body"}), 400
        user_message = data.get('message', '').strip()
        conversation_id = data.get('conversation_id', 'default')
        if not user_message:
            return jsonify({"error": "Üres üzenet"}), 400
        if conversation_id not in conversations:
            conversations[conversation_id] = []
        conversations[conversation_id].append({
            "role": "user",
            "content": user_message
        })
        print(f"[STREAM {conversation_id}] User: {user_message[:100]}...")

        def generate():
            full_response = ""
            try:
                stream = client.chat.completions.create(
                    model="gpt-oss-120b",
                    messages=conversations[conversation_id],
                    max_completion_tokens=65000,
                    reasoning_effort="low",
                    temperature=0.7,
                    stream=True
                )
                for chunk in stream:
                    if getattr(chunk, "choices", None) and getattr(chunk.choices[0], "delta", None) and getattr(chunk.choices[0].delta, "content", None):
                        content = chunk.choices[0].delta.content
                        full_response += content
                        yield f"data: {json.dumps({'content': content}, ensure_ascii=False)}\n\n"
                conversations[conversation_id].append({
                    "role": "assistant",
                    "content": full_response
                })
                print(f"[STREAM {conversation_id}] Teljes válasz: {len(full_response)} karakter")
                yield f"data: {json.dumps({'done': True})}\n\n"
            except Exception as e:
                print(f"❌ Streaming hiba: {str(e)}")
                traceback.print_exc()
                yield f"data: {json.dumps({'error': str(e)}, ensure_ascii=False)}\n\n"

        return Response(generate(), mimetype='text/event-stream', headers={
            'Cache-Control': 'no-cache',
            'X-Accel-Buffering': 'no'
        })
    except Exception as e:
        print(f"❌ Stream init hiba: {str(e)}")
        return jsonify({"error": f"Szerver hiba: {str(e)}"}), 500

@app.route('/api/conversation/clear', methods=['POST'])
def clear_conversation():
    data = request.get_json(silent=True) or {}
    conversation_id = data.get('conversation_id', 'default')
    if conversation_id in conversations:
        conversations[conversation_id] = []
    return jsonify({"success": True, "message": "Beszélgetés törölve"}), 200

@app.route('/api/conversation/history', methods=['GET'])
def get_history():
    conversation_id = request.args.get('conversation_id', 'default')
    history = conversations.get(conversation_id, [])
    return jsonify({"history": history}), 200

if __name__ == '__main__':
    port = int(os.environ.get('PORT', 5000))
    app.run(host='0.0.0.0', port=port, debug=True)
